local TopFullerMaker = {}
local PRODUCTS = {
    iron_topfuller = { name = "Železni zgornji fuller za utorjanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zgornji fuller za utorjanje za kovace." },
    bronze_topfuller = { name = "Bronast zgornji fuller za utorjanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zgornji fuller za utorjanje za kovace." },
    silver_topfuller = { name = "Srebrn zgornji fuller za utorjanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zgornji fuller za utorjanje za kovace." },
    gilded_topfuller = { name = "Pozlačen zgornji fuller za utorjanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zgornji fuller za utorjanje za kovace." },
    jewel_set_topfuller = { name = "Draguljast zgornji fuller za utorjanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zgornji fuller za utorjanje za kovace." },
    royal_sovereign_topfuller = { name = "Kraljevski suveren zgornji fuller za utorjanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zgornji fuller za utorjanje z biseri za krono." },
}
local BUILDINGS = {
    topfuller_workshop = { name = "Topfuller delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    topfuller_house = { name = "Topfuller hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_topfuller_atelier = { name = "Mojstrski topfuller atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_topfuller_palace = { name = "Suverena topfuller palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
TopFullerMaker.ironStock=18; TopFullerMaker.bronzeStock=14; TopFullerMaker.woodStock=10; TopFullerMaker.leatherStock=8; TopFullerMaker.silverStock=8; TopFullerMaker.goldStock=6; TopFullerMaker.jewelStock=4; TopFullerMaker.pearlStock=4
TopFullerMaker.productStock = {}; TopFullerMaker.buildings = {}; TopFullerMaker.maker = nil; TopFullerMaker.activeMaking = {}; TopFullerMaker.totalProducts = 0; TopFullerMaker.dayTimer = 0
function TopFullerMaker.init() TopFullerMaker.ironStock=18; TopFullerMaker.bronzeStock=14; TopFullerMaker.woodStock=10; TopFullerMaker.leatherStock=8; TopFullerMaker.silverStock=8; TopFullerMaker.goldStock=6; TopFullerMaker.jewelStock=4; TopFullerMaker.pearlStock=4; TopFullerMaker.productStock={}; TopFullerMaker.buildings={}; TopFullerMaker.maker=nil; TopFullerMaker.activeMaking={}; TopFullerMaker.totalProducts=0; TopFullerMaker.dayTimer=0; print("[TopFullerMaker] Royal Top Fuller Maker System initialized (6 products, 4 buildings)") end
function TopFullerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TopFullerMaker.maker={name=n or ("ZgornjiUtor "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("ZgornjiUtor najet: %s (spretnost: %d)",TopFullerMaker.maker.name,s),"success") end; return true end
function TopFullerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TopFullerMaker.build(id) local ok,e=TopFullerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TopFullerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TopFullerMaker.getQualityBonus() local b=0; for _,bd in ipairs(TopFullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TopFullerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TopFullerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TopFullerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TopFullerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TopFullerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TopFullerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TopFullerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TopFullerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TopFullerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TopFullerMaker.buildings==0 then return false,"Potrebna zgornjeutorjalna delavnica" end; if not TopFullerMaker.maker then return false,"Potreben zgornjiutor" end; return true end
function TopFullerMaker.make(pt,qty) qty=qty or 1; local ok,e=TopFullerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TopFullerMaker.ironStock=TopFullerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TopFullerMaker.bronzeStock=TopFullerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TopFullerMaker.woodStock=TopFullerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TopFullerMaker.leatherStock=TopFullerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TopFullerMaker.silverStock=TopFullerMaker.silverStock-d.silverCost*qty end; if d.goldCost then TopFullerMaker.goldStock=TopFullerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TopFullerMaker.jewelStock=TopFullerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TopFullerMaker.pearlStock=TopFullerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TopFullerMaker.maker then t=math.max(1,t-math.floor(TopFullerMaker.maker.skill/13)) end; table.insert(TopFullerMaker.activeMaking,{id="topfuller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TopFullerMaker.completeMaking(m) local q=1.0+(TopFullerMaker.getQualityBonus()/100); if TopFullerMaker.maker then q=q+(TopFullerMaker.maker.skill/140) end; q=math.min(2.5,q); TopFullerMaker.productStock[m.productType]=(TopFullerMaker.productStock[m.productType] or 0)+m.quantity; TopFullerMaker.totalProducts=TopFullerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TopFullerMaker.maker then TopFullerMaker.maker.itemsMade=TopFullerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TopFullerMaker.maker.skill=math.min(100,TopFullerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("ZgornjiUtor izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"topfuller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TopFullerMaker.update(dt) if not _G.state then return end; TopFullerMaker.dayTimer=TopFullerMaker.dayTimer+dt; if TopFullerMaker.dayTimer>=30 then TopFullerMaker.dayTimer=0; for i=#TopFullerMaker.activeMaking,1,-1 do local m=TopFullerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TopFullerMaker.completeMaking(m); table.remove(TopFullerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TopFullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TopFullerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TopFullerMaker.getStats() return {ironStock=TopFullerMaker.ironStock,bronzeStock=TopFullerMaker.bronzeStock,woodStock=TopFullerMaker.woodStock,leatherStock=TopFullerMaker.leatherStock,silverStock=TopFullerMaker.silverStock,goldStock=TopFullerMaker.goldStock,jewelStock=TopFullerMaker.jewelStock,pearlStock=TopFullerMaker.pearlStock,productStock=TopFullerMaker.productStock,numBuildings=#TopFullerMaker.buildings,hasMaker=TopFullerMaker.maker~=nil,makerName=TopFullerMaker.maker and TopFullerMaker.maker.name or "—",makerSkill=TopFullerMaker.maker and TopFullerMaker.maker.skill or 0,activeMaking=#TopFullerMaker.activeMaking,totalProducts=TopFullerMaker.totalProducts} end
return TopFullerMaker
